#!/usr/bin/env python3
import sys

def analyze_file(filename):
    with open(filename, 'rb') as f:
        data = f.read()

    # ELF magic number at the beginning should be \x7fELF
    if data[0:4] != b'\x7fELF':
        print("Warning: File does not start with ELF magic number")

    # Check the ELF class (32 or 64 bit)
    print(f"ELF class: {data[4]}")

    # Check the endianness
    print(f"Endianness: {data[5]}")

    # Check the ELF version
    print(f"Version: {data[6]}")

    # Check the OS ABI
    print(f"OS ABI: {data[7]}")

    # Check the ELF type
    print(f"Type: {data[16]}{data[17]}")

    # Check the machine
    print(f"Machine: {data[18]}{data[19]}")

    # Analyze the first few hundred bytes
    for i in range(0, 100, 16):
        print(f"{i:04x}: ", end="")
        for j in range(16):
            if i+j < len(data):
                print(f"{data[i+j]:02x} ", end="")
            else:
                print("   ", end="")
        print("  ", end="")
        for j in range(16):
            if i+j < len(data):
                if 32 <= data[i+j] <= 126:  # printable ASCII
                    print(chr(data[i+j]), end="")
                else:
                    print(".", end="")
            else:
                print(" ", end="")
        print()

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <elf_file>")
        sys.exit(1)

    analyze_file(sys.argv[1])

